const MATH_FORMULAS=[{category:"math",name:"Volume of Cube",formula:"V = a\xB3",explanation:"Volume of a cube is side multiplied by itself three times.",image:"media/photos/hello.jpg",keywords:"volume of cube cube formula"},{category:"math",name:"Pythagoras Theorem",formula:"c\xB2 = a\xB2 + b\xB2",explanation:"In a right-angled triangle, square of hypotenuse equals sum of squares of other two sides.",image:"images/formulas/pythagoras.png",keywords:"pythagoras theorem right triangle formula"},{category:"math",name:"Simple Interest",formula:"SI = (P \xD7 R \xD7 T) / 100",explanation:"Simple Interest is calculated on principal amount for a given time.",image:"images/formulas/simple-interest.png",keywords:"simple interest formula maths finance"},{category:"math",name:"Volume of Cylinder",formula:"V = \u03C0 \xD7 r\xB2 \xD7 h",explanation:"Volume of a cylinder is area of base multiplied by height.",image:"media/photos/fun.jpg",keywords:"volume cylinder formula"},{category:"math",name:"Surface Area of Sphere",formula:"A = 4\u03C0r\xB2",explanation:"Surface area of a sphere depends on radius.",image:"images/formulas/surface-sphere.png",keywords:"surface area sphere formula"},{category:"math",name:"Trapezium Area",formula:"A = \xBD \xD7 (a + b) \xD7 h",explanation:"Area of trapezium is half of sum of parallel sides multiplied by height.",image:"images/formulas/trapezium.png",keywords:"trapezium area formula"},{category:"math",name:"Area of Triangle",formula:"A = \xBD \xD7 b \xD7 h",explanation:"Area of triangle is half of base multiplied by height.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Triangle_area.svg/512px-Triangle_area.svg.png",keywords:"area triangle formula base height"},{category:"math",name:"Quadratic Formula",formula:"x = (\u2212b \xB1 \u221A(b\xB2 \u2212 4ac)) / 2a",explanation:"Used to find roots of a quadratic equation.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Quadratic_formula.svg/512px-Quadratic_formula.svg.png",keywords:"quadratic formula roots equation"},{category:"math",name:"Distance Formula",formula:"d = \u221A[(x\u2082 \u2212 x\u2081)\xB2 + (y\u2082 \u2212 y\u2081)\xB2]",explanation:"Distance between two points in coordinate geometry.",image:"https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Distance_formula.svg/512px-Distance_formula.svg.png",keywords:"distance formula coordinate geometry"},{category:"math",group:"Arithmetic",name:"Addition",formula:"a + b",explanation:"Addition combines two or more numbers into a single total.",image:"https://upload.wikimedia.org/wikipedia/commons/2/2d/Addition.svg",keywords:"addition sum plus arithmetic"},{category:"math",group:"Arithmetic",name:"Subtraction",formula:"a \u2212 b",explanation:"Subtraction finds the difference between two numbers.",image:"https://upload.wikimedia.org/wikipedia/commons/5/5b/Subtraction.svg",keywords:"subtraction minus difference arithmetic"},{category:"math",group:"Arithmetic",name:"Multiplication",formula:"a \xD7 b",explanation:"Multiplication is repeated addition of a number.",image:"https://upload.wikimedia.org/wikipedia/commons/3/3c/Multiplication.svg",keywords:"multiplication product times arithmetic"},{category:"math",group:"Arithmetic",name:"Division",formula:"a \xF7 b",explanation:"Division splits a number into equal parts.",image:"https://upload.wikimedia.org/wikipedia/commons/7/7e/Division.svg",keywords:"division quotient arithmetic"},{category:"math",group:"Geometry (Area)",name:"Area of Square",formula:"A = a\xB2",explanation:"Area of a square is side multiplied by itself.",image:"https://upload.wikimedia.org/wikipedia/commons/1/1e/Square_area.svg",keywords:"area square geometry"},{category:"math",group:"Geometry (Area)",name:"Area of Rectangle",formula:"A = l \xD7 b",explanation:"Area of rectangle is length multiplied by breadth.",image:"https://upload.wikimedia.org/wikipedia/commons/3/34/Rectangle_area.svg",keywords:"area rectangle geometry"},{category:"math",group:"Geometry (Area)",name:"Area of Circle",formula:"A = \u03C0r\xB2",explanation:"Area of a circle depends on the radius.",image:"https://upload.wikimedia.org/wikipedia/commons/3/3a/Circle_area.svg",keywords:"area circle pi geometry"},{category:"math",group:"Geometry (Perimeter)",name:"Perimeter of Square",formula:"P = 4a",explanation:"Perimeter is sum of all sides of a square.",image:"https://upload.wikimedia.org/wikipedia/commons/e/e4/Square_perimeter.svg",keywords:"perimeter square"},{category:"math",group:"Geometry (Perimeter)",name:"Circumference of Circle",formula:"C = 2\u03C0r",explanation:"Circumference is the boundary length of a circle.",image:"https://upload.wikimedia.org/wikipedia/commons/8/8c/Circle_circumference.svg",keywords:"circumference circle pi"},{category:"math",group:"Mensuration",name:"Volume of Cube",formula:"V = a\xB3",explanation:"Volume of cube is side cubed.",image:"https://upload.wikimedia.org/wikipedia/commons/3/36/Cube_volume.svg",keywords:"volume cube mensuration"},{category:"math",group:"Mensuration",name:"Volume of Cylinder",formula:"V = \u03C0r\xB2h",explanation:"Volume of cylinder equals base area times height.",image:"https://upload.wikimedia.org/wikipedia/commons/4/4c/Cylinder_volume.svg",keywords:"volume cylinder"},{category:"math",group:"Mensuration",name:"Surface Area of Sphere",formula:"A = 4\u03C0r\xB2",explanation:"Surface area of sphere depends on radius.",image:"https://upload.wikimedia.org/wikipedia/commons/6/6f/Sphere_surface_area.svg",keywords:"surface area sphere"},{category:"math",group:"Algebra",name:"Quadratic Formula",formula:"x = (\u2212b \xB1 \u221A(b\xB2 \u2212 4ac)) / 2a",explanation:"Used to find roots of quadratic equations.",image:"https://upload.wikimedia.org/wikipedia/commons/9/9e/Quadratic_formula.svg",keywords:"quadratic formula algebra"},{category:"math",group:"Algebra",name:"Linear Equation",formula:"ax + b = 0",explanation:"Simplest form of algebraic equation.",image:"https://upload.wikimedia.org/wikipedia/commons/1/1c/Linear_equation.svg",keywords:"linear equation algebra"},{category:"math",group:"Trigonometry",name:"Sine",formula:"sin\u03B8 = opposite / hypotenuse",explanation:"Sine ratio in a right-angled triangle.",image:"https://upload.wikimedia.org/wikipedia/commons/9/9b/Trigonometry_triangle.svg",keywords:"sine trigonometry"},{category:"math",group:"Trigonometry",name:"Cosine",formula:"cos\u03B8 = adjacent / hypotenuse",explanation:"Cosine ratio in a right-angled triangle.",image:"https://upload.wikimedia.org/wikipedia/commons/9/9b/Trigonometry_triangle.svg",keywords:"cosine trigonometry"},{category:"math",group:"Trigonometry",name:"Tangent",formula:"tan\u03B8 = opposite / adjacent",explanation:"Tangent ratio in a right-angled triangle.",image:"https://upload.wikimedia.org/wikipedia/commons/9/9b/Trigonometry_triangle.svg",keywords:"tangent trigonometry"},{category:"math",group:"Coordinate Geometry",name:"Distance Formula",formula:"d = \u221A[(x\u2082 \u2212 x\u2081)\xB2 + (y\u2082 \u2212 y\u2081)\xB2]",explanation:"Distance between two points in XY plane.",image:"https://upload.wikimedia.org/wikipedia/commons/6/6d/Distance_formula.svg",keywords:"distance formula coordinate geometry"},{category:"math",group:"Coordinate Geometry",name:"Midpoint Formula",formula:"((x\u2081+x\u2082)/2 , (y\u2081+y\u2082)/2)",explanation:"Finds midpoint between two points.",image:"https://upload.wikimedia.org/wikipedia/commons/8/8e/Midpoint_formula.svg",keywords:"midpoint formula coordinate"},{category:"math",group:"Finance",name:"Simple Interest",formula:"SI = (P \xD7 R \xD7 T) / 100",explanation:"Interest calculated on principal amount.",image:"https://upload.wikimedia.org/wikipedia/commons/3/3a/Simple_interest.svg",keywords:"simple interest finance"},{category:"math",group:"Finance",name:"Compound Interest",formula:"CI = P(1 + R/100)\u1D57 \u2212 P",explanation:"Interest calculated on accumulated amount.",image:"https://upload.wikimedia.org/wikipedia/commons/2/24/Compound_interest.svg",keywords:"compound interest finance"},{category:"math",group:"Calculus",name:"Derivative of x\u207F",formula:"d/dx (x\u207F) = n x\u207F\u207B\xB9",explanation:"Power rule of differentiation.",image:"https://upload.wikimedia.org/wikipedia/commons/8/8c/Power_rule.svg",keywords:"derivative power rule"},{category:"math",group:"Calculus",name:"\u222B x\u207F dx",formula:"x\u207F\u207A\xB9 / (n+1) + C",explanation:"Power rule of integration.",image:"https://upload.wikimedia.org/wikipedia/commons/2/2f/Integral_power_rule.svg",keywords:"integration calculus"}];
